#[path="../../../../../../../../../../🧰️framework/🔨️modules/🌱️value/📽️projection/👁️post/🧪️testing/🦀️.rs"]
mod post_fixture;
use post_fixture::PostFixture;
use super::*;
use crate::schema::diff::{IdmlPatch,IdmlPartPatch};
use semio_framework_value::{retirement::RetireOwned,retained_clone::RetainedCloneSource};
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn source<T:RetireOwned+Sync+'static>(value:T)->RetainedCloneSource<T>{match RetainedCloneSource::admit_owned(value,(),RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:1<<24,maximum_capacity_bytes:1<<24,maximum_release_bytes:1<<24,maximum_depth:4096}){Ok((owner,_))=>owner,Err((error,_,_))=>panic!("{error}")}}
fn close_source<T:RetireOwned+Sync+'static>(owner:&mut RetainedCloneSource<T>){for _ in 0..100000{if owner.terminal_is_empty(){return;}let d=RetirementDemand{copy_bytes:owner.next_close_copy_byte_demand().unwrap(),capacity_bytes:owner.next_close_capacity_byte_demand(4096).unwrap(),release_bytes:owner.next_close_release_byte_demand().unwrap(),depth:owner.next_close_depth_demand().unwrap()};owner.close_step(grant(d)).unwrap();}panic!("original source close stalled");}
fn close_messages(rows:Vec<MutationMessage>){let mut ledger=MutationMessageLedgerRetirement::new(String::new(),rows);while !ledger.terminal_is_empty(){let d=semio_framework_value::ErasedSnapshotRetirement::next_demand(&ledger,4096).unwrap();ledger.close_step(grant(d)).unwrap();}}
fn close(owner:&mut protocol::RetainedDiffOwner<IdmlSnapshot,IdmlDiff>){owner.begin_close();for _ in 0..100000{if owner.terminal_is_empty(){return;}let d=owner.close_demand(4096).unwrap();assert_eq!(owner.close_step(RetainedCloneGrant::default()).unwrap().progress(),Default::default());owner.close_step(grant(d)).unwrap();}panic!("IDML central apply close stalled");}
fn inputs(corpus:&serde_json::Value,row:&serde_json::Value)->(IdmlSnapshot,IdmlSnapshot,IdmlDiff){let base=IdmlSnapshot{dom_version:corpus["base"]["domVersion"].as_str().unwrap().into(),parts:corpus["base"]["parts"].as_array().unwrap().iter().map(|part|IdmlPart{path:part["path"].as_str().unwrap().into(),bytes:part["text"].as_str().unwrap().as_bytes().to_vec()}).collect()};let mut post=base.clone();if row["post"].is_object(){post.parts.iter_mut().find(|part|part.path==row["post"]["path"].as_str().unwrap()).unwrap().bytes=row["post"]["text"].as_str().unwrap().as_bytes().to_vec();}let diff=IdmlDiff{steps:row["steps"].as_array().unwrap().iter().map(|step|IdmlPatch{dom_version:step["domVersion"].as_str().map(str::to_string),part_order:step["partOrder"].as_array().map(|values|values.iter().map(|value|value.as_str().unwrap().to_string()).collect()),parts:step["parts"].as_array().unwrap().iter().map(|part|IdmlPartPatch{path:part["path"].as_str().unwrap().into(),bytes:if part["remove"]==true{None}else if let Some(text)=part["text"].as_str(){Some(text.as_bytes().to_vec())}else{Some(part["bytes"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as u8).collect())}}).collect()}).collect()};(base,post,diff)}
#[test]
fn real_central_owner_retains_original_sources_and_moves_untouched_live_payload(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../../🗺️overlay/🧪️fixtures/🔣️.json")).unwrap();for row in corpus["cases"].as_array().unwrap(){for body in [1024,4096,65536]{let(base,post,diff)=inputs(&corpus,row);let mut post=PostFixture::new(post);let expected=protocol::apply_diff_cold(&diff,&post);let original=base.clone();let event=diff.clone();let unchanged=post.clone();let pointer=post.parts[2].bytes.as_ptr();let mut base=source(base);let mut diff=source(diff);let(mut owner,_)=protocol::begin_retained_diff::<IdmlSnapshot,IdmlDiff>(grant(protocol::retained_diff_birth_demand::<IdmlSnapshot,IdmlDiff>())).unwrap();let mut callback=|_|true;let mut receiving=semio_framework_value::NativeDecodeControl::new(1<<30,&mut callback);let mut turns=0;let admitted=loop{turns+=1;assert!(turns<1000000);let d=owner.preflight_demand(diff.borrow(),base.borrow(),post.borrow(),body).unwrap();assert_eq!(protocol::preflight_retained_diff(&mut owner,diff.borrow(),base.borrow(),post.borrow(),body,RetainedCloneGrant::default(),&mut receiving).unwrap().progress(),Default::default());let step=protocol::preflight_retained_diff(&mut owner,diff.borrow(),base.borrow(),post.borrow(),body,grant(d),&mut receiving).unwrap();assert!(step.progress().fits(grant(d)));assert_eq!(post,unchanged);match step{protocol::RetainedDiffPreflightStep::Progress(_)=>{},protocol::RetainedDiffPreflightStep::Admitted(_,rows)=>{close_messages(rows);break true;},protocol::RetainedDiffPreflightStep::Refused(_,rows)=>{assert!(!rows.is_empty());close_messages(rows);break false;}}};assert_eq!(admitted,row["error"].is_null());if admitted{for _ in 0..100000{let d=owner.commit_demand(diff.borrow(),base.borrow(),post.mutable_read(),body).unwrap();assert_eq!(protocol::commit_retained_diff(&mut owner,diff.borrow(),base.borrow(),&mut post,RetainedCloneGrant::default()).unwrap().progress(),Default::default());let step=protocol::commit_retained_diff(&mut owner,diff.borrow(),base.borrow(),&mut post,grant(d)).unwrap();assert!(step.progress().fits(grant(d)));if matches!(step,RetainedCloneStep::Complete(_)){break;}}assert_eq!(post,expected.unwrap());if row["id"]=="preserve-live-post-field"{assert_eq!(post.parts.iter().find(|part|part.path=="Stories/A.xml").unwrap().bytes.as_ptr(),pointer);}}else{assert_eq!(post,unchanged);}assert_eq!(base.borrow().get(),&original);assert_eq!(diff.borrow().get(),&event);close(&mut owner);close_source(&mut diff);close_source(&mut base);let mut final_post=source(post.into_inner());close_source(&mut final_post);}}}
#[test]
fn cancellation_keeps_every_original_diff_frontier_closeable(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../../🗺️overlay/🧪️fixtures/🔣️.json")).unwrap();for cut in [0,1,5,50,100,250]{let(base,post,diff)=inputs(&corpus,&corpus["cases"][1]);let post=PostFixture::new(post);let unchanged=post.clone();let mut base=source(base);let mut diff=source(diff);let(mut owner,_)=protocol::begin_retained_diff::<IdmlSnapshot,IdmlDiff>(grant(protocol::retained_diff_birth_demand::<IdmlSnapshot,IdmlDiff>())).unwrap();let mut callback=|_|true;let mut receiving=semio_framework_value::NativeDecodeControl::new(1<<30,&mut callback);for _ in 0..cut{let d=owner.preflight_demand(diff.borrow(),base.borrow(),post.borrow(),1024).unwrap();match protocol::preflight_retained_diff(&mut owner,diff.borrow(),base.borrow(),post.borrow(),1024,grant(d),&mut receiving).unwrap(){protocol::RetainedDiffPreflightStep::Progress(_)=>{},protocol::RetainedDiffPreflightStep::Admitted(_,rows)|protocol::RetainedDiffPreflightStep::Refused(_,rows)=>{close_messages(rows);break;}}}assert_eq!(post,unchanged);close(&mut owner);close_source(&mut diff);close_source(&mut base);let mut final_post=source(post.into_inner());close_source(&mut final_post);}}
